def diff_even_odd(nums):
    first_even = None
    first_odd = None

    for n in nums:
        if n % 2 == 0 and first_even is None:
            first_even = n
        elif n % 2 != 0 and first_odd is None:
            first_odd = n

        if first_even is not None and first_odd is not None:
            return first_even - first_odd

    return 0
